INSERT INTO `standard_tasks` (`id`, `sub_service_id`, `title`, `description`, `type`, `priority`, `estimated_hours`, `technical_complexity`, `technologies`, `required_accesses`, `environment`, `technical_notes`, `is_active`, `order`, `created_at`, `updated_at`) VALUES (1,1,'Diagnóstico del error reportado','Identificar y documentar el error en el contenido publicado','regular','high',0.50,NULL,NULL,NULL,NULL,NULL,1,1,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(2,1,'Corrección del contenido','Aplicar correcciones necesarias al contenido','regular','high',1.00,NULL,NULL,NULL,NULL,NULL,1,2,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(3,1,'Verificación y cierre','Verificar que el error ha sido corregido completamente','regular','medium',0.50,NULL,NULL,NULL,NULL,NULL,1,3,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(4,12,'Revisión de contenido a publicar','Validar contenido y requisitos de publicación','regular','medium',0.50,NULL,NULL,NULL,NULL,NULL,1,1,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(5,12,'Preparación y publicación','Preparar y publicar el contenido','regular','medium',1.00,NULL,NULL,NULL,NULL,NULL,1,2,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(6,12,'Verificación post-publicación','Verificar correcta publicación del contenido','regular','medium',0.25,NULL,NULL,NULL,NULL,NULL,1,3,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(7,29,'Análisis de requerimientos','Analizar y documentar requerimientos técnicos','impact','high',2.00,NULL,NULL,NULL,NULL,NULL,1,1,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(8,29,'Diseño de solución','Diseñar arquitectura y componentes','impact','high',3.00,NULL,NULL,NULL,NULL,NULL,1,2,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(9,29,'Implementación','Desarrollar la solución técnica','impact','high',8.00,NULL,NULL,NULL,NULL,NULL,1,3,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(10,29,'Pruebas y despliegue','Realizar pruebas y desplegar en producción','impact','high',2.00,NULL,NULL,NULL,NULL,NULL,1,4,'2025-11-19 02:48:17','2025-11-19 02:48:17'),(11,16,'Revisión y corrección de enlaces rotos en página de trámites y servicios',NULL,'regular','high',3.10,3,'PHP, Drupal',NULL,'production',NULL,1,1,'2025-12-04 16:13:29','2025-12-04 16:13:29'),(12,5,'Actualización de enlace de formulario para cursos de motociclistas',NULL,'regular','medium',1.60,NULL,NULL,NULL,NULL,NULL,1,0,'2025-12-04 16:21:05','2025-12-04 16:21:05'),(13,9,'Publicación de Instructivos en Página Web Institucional','Publicar instructivos o cartillas informativas en el portal web, garantizando su accesibilidad y ubicación adecuada para el acceso de los ciudadanos.','regular','medium',1.10,2,'Gestor de Contenidos (CMS), HTML, PDF','CMS Institucional, VPN','production','Asegurar que los archivos PDF publicados cumplan con estándares básicos de accesibilidad (texto seleccionable, etiquetado correcto).',1,0,'2025-12-04 16:57:49','2025-12-04 16:57:49'),(14,34,'Publicación de banner','Montar el banner proporcionado por la Oficina de Comunicaciones en el sitio web institucional, configurándolo para que direccione alojado en la ruta proporcionada.','regular','medium',1.10,2,'CMS Institucional, HTML, Gestor de Archivos','Acceso al CMS de la página web, gestor de archivos del sitio','production',NULL,1,0,'2025-12-04 19:25:52','2025-12-04 19:26:18'),(15,5,'Solicitud de Edición o Ajuste de Contenido en Página Web','Realizar modificaciones, actualizaciones o correcciones específicas al contenido textual, gráfico o multimedia de una página o sección del sitio web institucional, conforme a la solicitud recibida.','regular','medium',1.60,2,'CMS Institucional (Ej: Drupal, WordPress), HTML básico, Editor de texto enriquecido, Gestor de Medios.','Credenciales de editor/administrador de contenido en el CMS.','production','Especificar la URL exacta de la página a editar.\r\n\r\n    Adjuntar el contenido nuevo (texto, imágenes corregidas, enlaces) y la referencia clara de lo que se debe cambiar (ej: \"reemplazar el párrafo 2 por el texto anexo\", \"actualizar la imagen del banner principal\").\r\n\r\n    Considerar pautas de accesibilidad web en las ediciones (texto alternativo en imágenes, contraste, estructura de encabezados).',1,0,'2025-12-04 20:56:05','2025-12-04 20:56:05'),(16,23,'Publicación de Noticia, PMT o Artículo en Portal Web Institucional','Gestionar el proceso completo de publicación de un contenido informativo (noticia, artículo o PMT - Página de Mínima Temporal) en el portal web, asegurando su correcta redacción, formato, ubicación y visibilidad conforme a los lineamientos editoriales y técnicos.','regular','medium',2.10,3,'CMS Institucional (ej: Drupal, WordPress), Editor de texto enriquecido, Gestor de Medios, Herramientas de SEO básico.','Credenciales de editor/administrador de contenido en el CMS, acceso a repositorio de imágenes institucionales.','production','El contenido debe cumplir con la guía de estilo editorial (tono, longitud, estructura).\r\n\r\n    Optimizar imágenes (peso, dimensiones, texto alternativo descriptivo).\r\n\r\n    Configurar metadatos básicos (título SEO, descripción breve).\r\n\r\n    Definir categorías/tags y la sección o página principal de destino.\r\n\r\n    Asegurar que sea responsive y accesible.',1,0,'2025-12-04 21:03:13','2025-12-04 21:03:13'),(17,190,'Levantamiento de requerimientos y alcance','Reunión o análisis del requerimiento para definir estructura, secciones, funcionalidades y contenido del sitio/landing.','impact','high',2.00,2,NULL,NULL,'development','Definir: secciones, navegación, contenido necesario, fecha de publicación.',1,1,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(18,190,'Diseño y maquetación de estructura','Crear la estructura del sitio/landing según los requerimientos definidos. Incluye wireframe o boceto de secciones.','impact','high',4.00,3,NULL,NULL,'development','Considerar responsive, accesibilidad y lineamientos de Gobierno Digital.',1,2,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(19,190,'Desarrollo e implementación técnica','Construcción del sitio/landing: templates, componentes, integración de contenido multimedia, formularios si aplica.','impact','high',12.00,4,NULL,NULL,'development','Desarrollo en ambiente local/staging. No publicar sin aprobación.',1,3,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(20,190,'Pruebas y revisión de contenidos','Verificar funcionamiento en navegadores, responsive, enlaces, formularios. Validar contenidos con el área solicitante.','impact','medium',3.00,2,NULL,NULL,'staging','Probar en Chrome, Firefox, Safari. Validar en móvil.',1,4,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(21,190,'Despliegue a producción y verificación','Publicar el sitio/landing en producción. Verificar URLs, SEO básico, accesibilidad. Informar al solicitante.','regular','high',1.50,2,NULL,NULL,'production','Verificar que URLs sean amigables y el sitio sea indexable.',1,5,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(22,182,'Definición de alcance y contenido de la sección/campaña','Coordinar con el área solicitante para definir estructura, contenido, plazos y objetivos de la sección especial o campaña.','impact','medium',2.00,2,NULL,NULL,'development',NULL,1,1,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(23,182,'Diseño y construcción de la sección/campaña','Crear la estructura web, templates y componentes necesarios para la sección especial o campaña digital.','impact','high',8.00,3,NULL,NULL,'development',NULL,1,2,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(24,182,'Carga de contenido y validación','Incorporar textos, imágenes, documentos y multimedia. Validar con el área solicitante.','regular','medium',3.00,1,NULL,NULL,'staging',NULL,1,3,'2026-08-19 23:32:26','2026-08-19 23:32:26'),(25,182,'Publicación y comunicación al solicitante','Publicar en producción y confirmar con el área solicitante la disponibilidad.','regular','medium',1.00,1,NULL,NULL,'production',NULL,1,4,'2026-08-19 23:32:26','2026-08-19 23:32:26');
