INSERT INTO `tasks` (`id`, `task_code`, `type`, `title`, `description`, `service_request_id`, `technician_id`, `owner_id`, `project_id`, `standard_task_id`, `sla_id`, `scheduled_date`, `due_date`, `due_time`, `scheduled_start_time`, `scheduled_order`, `estimated_hours`, `time_blocks`, `actual_hours`, `scheduled_time`, `estimated_duration_minutes`, `actual_duration_minutes`, `priority`, `is_critical`, `status`, `technical_complexity`, `required_accesses`, `dependencies`, `technologies`, `git_repository`, `git_branch`, `git_pr_url`, `environment`, `technical_notes`, `requires_evidence`, `evidence_completed`, `research_time_minutes`, `started_at`, `blocked_at`, `block_reason`, `completed_at`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'REG-20251118-001','regular','Cargar en la carpeta de drive los informes pendientes de febrero, agosto y septiembre de 2025','Cargar en la carpeta de drive los informes pendientes de febrero, agosto y septiembre de 2025.',128,3,NULL,NULL,NULL,1,'2025-11-18 00:00:00',NULL,NULL,'11:00:00',0,0.4,1,NULL,NULL,NULL,NULL,'medium',0,'completed',3,'\"[]\"',NULL,'\"[]\"',NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-03 16:24:52','2025-11-17 14:48:14','2025-12-03 16:24:52',NULL),(2,'REG-20251118-002','regular','Incluir los certificados y evidencias correspondientes para cada informe pendiente.','- Incluir los certificados y evidencias correspondientes para cada informe pendiente.',128,3,NULL,NULL,NULL,1,'2025-11-18 00:00:00',NULL,NULL,'09:00:00',0,0.4,1,NULL,NULL,NULL,NULL,'low',0,'completed',2,'\"[]\"',NULL,'\"[]\"',NULL,NULL,NULL,'staging',NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-03 16:24:51','2025-11-17 14:50:59','2025-12-03 16:24:51',NULL),(3,'IMP-20251118-001','impact','Completar y cargar informes mensuales pendientes en drive','Se requiere completar y cargar en la carpeta de drive designada los informes mensuales pendientes de febrero, agosto y septiembre de 2025, incluyendo sus certificados y evidencias correspondientes. Para los informes de octubre y julio, se deben agregar las evidencias faltantes.',128,3,NULL,NULL,NULL,1,'2025-11-18 00:00:00',NULL,NULL,'14:30:00',0,1.5,1,NULL,NULL,NULL,NULL,'high',0,'completed',3,NULL,NULL,NULL,NULL,NULL,NULL,'production',NULL,1,0,NULL,'2025-11-18 14:31:36',NULL,NULL,'2025-12-03 16:24:50','2025-11-18 14:24:21','2025-12-03 16:24:50',NULL),(4,'IMP-20251125-001','impact','Reporte ajustes nuevo sitio web','Revisión y ajuste de observaciones en el nuevo sitio web\r\n\r\nSe requiere revisar y ajustar varias observaciones identificadas en el nuevo sitio web, con prioridad en la corrección de los perfiles que se muestran sin las últimas actualizaciones. La lista detallada de observaciones se encuentra en el documento de Google compartido.',113,3,NULL,NULL,NULL,1,'2025-11-24 00:00:00',NULL,NULL,'16:00:00',0,1.3,1,NULL,'08:00:00',80,NULL,'urgent',0,'in_progress',NULL,'[]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,1,0,NULL,'2025-11-24 22:14:58',NULL,NULL,NULL,'2025-11-24 20:24:49','2025-11-25 22:33:22','2025-11-25 22:33:22'),(5,'IMP-20251126-001','impact','Reporte ajustes nuevo sitio web','Problemas de contenido en páginas de sistemas de gestión\r\n\r\nCorrección de imágenes, enlaces y contenido en páginas de sistemas de gestión\r\n\r\nSe reportan múltiples problemas en las páginas de sistemas de gestión incluyendo imágenes no visibles, enlaces rotos, contenido desorganizado, logos desactualizados, texto cortado y vínculos con texto falso, requiriendo corrección urgente.',113,3,NULL,NULL,NULL,1,'2025-11-26 00:00:00',NULL,NULL,'09:00:00',0,3.8,1,NULL,'09:00:00',225,NULL,'high',0,'completed',NULL,'[]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-11-26 18:11:07','2025-11-25 22:39:05','2025-11-26 18:11:07',NULL),(6,'REG-20251127-001','regular','Publicación Adicional 1 de COOS 44 de 2025','Publicación de Adicional Contractual en el Portal Web SDM\r\n\r\nLa acción consiste en gestionar la publicación del documento Adicional 1 de COOS 44 de 2025 en el nuevo portal web de la Secretaría, cumpliendo con los procedimientos establecidos para la divulgación oficial de información contractual.',84,3,NULL,NULL,NULL,5,'2026-08-24 00:00:00',NULL,NULL,'17:35:00',0,0.4,1,0.0,'17:35:00',25,1,'urgent',0,'completed',NULL,'[]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,1,1,NULL,'2026-08-25 00:16:27',NULL,NULL,'2026-08-25 00:16:27','2025-11-27 19:53:24','2026-08-25 00:16:27',NULL),(7,'IMP-20251128-001','impact','Esquema de Publicación Ley de Transparencia y Acceso a la Información','Actualización de Contenidos para Transparencia\r\n\r\nSolicitud para completar la publicación de documentos pendientes en el apartado de transparencia y acceso a la información del portal web de la secretaría, de acuerdo con la matriz de observaciones proporcionada.\r\n\r\n- Revisar la matriz de observaciones con los documentos faltantes y pendientes.\r\n- Actualizar el apartado de transparencia en el portal web con los documentos requeridos.\r\n- Verificar que las observaciones previas en color rojo hayan sido atendidas.\r\n- Confirmar la finalización de la publicación con los solicitantes.',101,3,NULL,NULL,NULL,1,'2025-11-28 00:00:00',NULL,NULL,'08:00:00',0,1.5,4,NULL,'08:00:00',90,NULL,'urgent',0,'completed',NULL,'[]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2026-08-24 16:16:25','2025-11-27 22:53:24','2026-08-24 16:16:25',NULL),(8,'IMP-20251202-001','regular','Ajuste contenido WEB - Control Disciplinario','Corrección de información de contacto en página web\r\n\r\nSe requiere ajustar el correo electrónico publicado en el sitio web de la Oficina de Control Disciplinario Interno, ya que el punto migrado contiene una dirección errónea.',107,3,NULL,NULL,NULL,1,'2025-12-16 00:00:00',NULL,NULL,'15:00:00',0,4.5,11,NULL,'08:00:00',55,NULL,'urgent',0,'completed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2026-08-24 23:55:36','2025-12-02 12:00:21','2026-08-24 23:55:36',NULL),(9,'IMP-20251204-001','impact','Validación accesibilidad web VUS','Elaboración de documento técnico para ajuste de paleta de colores\r\n\r\nSolicitud para elaborar un documento técnico con recomendaciones que orienten el manejo adecuado de la paleta de colores institucional, tras identificarse incumplimientos en los niveles de contraste AAA de accesibilidad web en el portal transaccional CIDI. El documento debe garantizar el cumplimiento del nivel AAA, preservando la coherencia con la paleta institucional y sin afectar su aplicación en el portal.\r\n\r\n- Elaborar un documento técnico con recomendaciones para el manejo de la paleta de colores.\r\n- Garantizar que las recomendaciones cumplan con el nivel de accesibilidad AAA.\r\n- Verificar que se preserve la coherencia con la paleta de colores institucional.\r\n- Asegurar que las recomendaciones no afecten la aplicación de la paleta en el portal.',119,3,NULL,NULL,NULL,7,'2025-12-05 00:00:00',NULL,NULL,'08:30:00',0,1.5,4,NULL,'08:00:00',90,NULL,'medium',0,'completed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2026-08-25 00:20:49','2025-12-03 15:36:53','2026-08-25 00:20:49',NULL),(10,'REG-20251204-001','regular','Diagnóstico del error reportado','Identificar y documentar el error en el contenido publicado',140,3,NULL,NULL,NULL,1,'2025-12-04 17:44:06',NULL,NULL,'08:00:00',0,0.5,1,NULL,NULL,NULL,NULL,'high',0,'completed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-03 17:44:20','2025-12-03 17:44:06','2025-12-03 17:44:20',NULL),(11,'REG-20251204-002','regular','Corrección del contenido','Aplicar correcciones necesarias al contenido',140,3,NULL,NULL,NULL,1,'2025-12-04 17:44:06',NULL,NULL,'08:00:00',0,1.0,1,NULL,NULL,NULL,NULL,'high',0,'completed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-03 17:44:26','2025-12-03 17:44:06','2025-12-03 17:44:26',NULL),(12,'REG-20251204-003','regular','Verificación y cierre','Verificar que el error ha sido corregido completamente',140,3,NULL,NULL,NULL,1,'2025-12-04 17:44:06',NULL,NULL,'08:00:00',0,0.5,1,NULL,NULL,NULL,NULL,'medium',0,'completed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-03 17:44:29','2025-12-03 17:44:06','2025-12-03 17:44:29',NULL),(13,'IMP-20251205-001','impact','Revisión y verificación de enlaces y accesibilidad de documentos en sitio web en construcción','Mejora de la Funcionalidad de Búsqueda y Actualización de Contenidos para la Subdirección de Infraestructura\r\n\r\nImplementar las correcciones y observaciones detalladas en el documento \"Validación de contenidos en el nuevo portal web_Observaciones SI\" para garantizar la integridad, exactitud y ubicación correcta de toda la información bajo la competencia de la Subdirección de Infraestructura. Adicionalmente, se debe optimizar la precisión del módulo de búsqueda del portal web para que filtre eficazmente los resultados utilizando palabras clave o el nombre completo de los recursos solicitados, mejorando así su funcionalidad y usabilidad para el usuario.',56,3,NULL,NULL,NULL,1,'2025-12-05 00:00:00',NULL,NULL,'11:45:00',0,1.0,1,NULL,'11:45:00',60,NULL,'high',0,'completed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-05 16:51:13','2025-12-05 16:36:54','2025-12-05 16:51:13',NULL),(14,'REG-20251206-001','regular','Solicitud de actualización - Formulario de inscripción curso de motos','Actualizar enlace de formulario web\r\n\r\nSe requiere actualizar el enlace del formulario de inscripción para los cursos de conducción de motocicletas en la página web oficial.',181,3,NULL,NULL,NULL,1,'2025-12-06 00:00:00',NULL,'17:00:00','13:30:00',0,0.4,1,NULL,'13:30:00',25,NULL,'medium',0,'completed',NULL,'[]',NULL,'[]',NULL,NULL,NULL,NULL,NULL,1,0,NULL,NULL,NULL,NULL,'2025-12-06 14:39:25','2025-12-06 13:20:47','2025-12-06 14:39:25',NULL),(15,'REG-20251206-002','regular','Asignación Radicado # 202561000246243 DAF RESPUESTA MEMORANDO 202511000215863','Gestión de asignación de radicado